-- =========================================================================
-- SQL Script to Delete Specific Products by Barcode
-- Database: pos_billing_db / MySQL
-- =========================================================================

-- Target Barcodes:
-- 8908001000017, 8908001000451, 8908001000659, 8908001000697, 8908001000710,
-- 8908001000819, 8908001000826, 8908001000840, 8908001000857, 8908001000864,
-- 8908001000871, 8908001000888, 8908001000895, 8908001000901, 8908001000918,
-- 8908001000925, 8908001000932, 8908001000949, 8908001000956, 8908001000963,
-- 8908001000987

START TRANSACTION;

-- Step 1: Preview the products that will be deleted (Optional verification)
SELECT id, sku, barcode, name, category, selling_price, stock_quantity 
FROM products 
WHERE barcode IN (
  '8908001000017', '8908001000451', '8908001000659', '8908001000697', '8908001000710',
  '8908001000819', '8908001000826', '8908001000840', '8908001000857', '8908001000864',
  '8908001000871', '8908001000888', '8908001000895', '8908001000901', '8908001000918',
  '8908001000925', '8908001000932', '8908001000949', '8908001000956', '8908001000963',
  '8908001000987'
);

-- Step 2: Delete related inventory logs to prevent foreign key constraint violations
DELETE FROM inventory_logs 
WHERE product_id IN (
  SELECT id FROM (
    SELECT id FROM products 
    WHERE barcode IN (
      '8908001000017', '8908001000451', '8908001000659', '8908001000697', '8908001000710',
      '8908001000819', '8908001000826', '8908001000840', '8908001000857', '8908001000864',
      '8908001000871', '8908001000888', '8908001000895', '8908001000901', '8908001000918',
      '8908001000925', '8908001000932', '8908001000949', '8908001000956', '8908001000963',
      '8908001000987'
    )
  ) AS p
);

-- Step 3: Unlink from invoice_items so completed sales invoices are not broken
UPDATE invoice_items 
SET product_id = NULL 
WHERE product_id IN (
  SELECT id FROM (
    SELECT id FROM products 
    WHERE barcode IN (
      '8908001000017', '8908001000451', '8908001000659', '8908001000697', '8908001000710',
      '8908001000819', '8908001000826', '8908001000840', '8908001000857', '8908001000864',
      '8908001000871', '8908001000888', '8908001000895', '8908001000901', '8908001000918',
      '8908001000925', '8908001000932', '8908001000949', '8908001000956', '8908001000963',
      '8908001000987'
    )
  ) AS p
);

-- Step 4: Delete the target products
DELETE FROM products 
WHERE barcode IN (
  '8908001000017', '8908001000451', '8908001000659', '8908001000697', '8908001000710',
  '8908001000819', '8908001000826', '8908001000840', '8908001000857', '8908001000864',
  '8908001000871', '8908001000888', '8908001000895', '8908001000901', '8908001000918',
  '8908001000925', '8908001000932', '8908001000949', '8908001000956', '8908001000963',
  '8908001000987'
);

COMMIT;
